from pyspark.sql import functions as F


def solve(employees):
    e = employees.alias("e")
    m = employees.alias("m")
    pairs = e.join(m, F.col("e.employee_id") == F.col("m.manager_id"), "left")
    return pairs.select(
        F.col("e.employee_id").alias("employee_id"),
        F.col("e.job_title").alias("job_title"),
        F.col("m.job_title").alias("manager_title"),
    )
